  1	package hotel.reservations;
  2	
  3	public enum RatePlan {
  4	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
  5	    STANDARD,
  6	    /** 15% off, but nothing comes back on cancellation. */
  7	    NON_REFUNDABLE,
  8	    /** Corporate discount based on company code; full refund on cancellation. */
  9	    CORPORATE,
 10	    /** Fixed weekend package price (Friday to Sunday); 50% refund on cancellation. */
 11	    WEEKEND_PACKAGE,
 12	    /** 10% discount for stays of 7 nights or more; full refund on cancellation. */
 13	    LONG_STAY
 14	}
 15	package hotel.reservations;
 16	
 17	import hotel.rooms.Room;
 18	import hotel.rooms.RoomType;
 19	import java.math.BigDecimal;
 20	import java.math.RoundingMode;
 21	import java.time.DayOfWeek;
 22	import java.time.LocalDate;
 23	import java.time.Month;
 24	import java.util.Map;
 25	
 26	/**
 27	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 28	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 29	 * (half-even) at every step.
 30	 */
 31	public final class PriceCalculator {
 32	
 33	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 34	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 35	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 36	
 37	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 38	            "TECNOSUL", new BigDecimal("0.12"),
 39	            "AGROVALE", new BigDecimal("0.18"),
 40	            "FARMAVIDA", new BigDecimal("0.25"));
 41	
 42	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 43	            RoomType.STANDARD, new BigDecimal("520.00"),
 44	            RoomType.DELUXE, new BigDecimal("820.00"),
 45	            RoomType.SUITE, new BigDecimal("1200.00"));
 46	
 47	    public Price calculate(
 48	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 49	        int nights = 0;
 50	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 51	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 52	            subtotal = subtotal.add(nightPrice(room, night));
 53	            nights++;
 54	        }
 55	
 56	        BigDecimal discount;
 57	        BigDecimal total;
 58	
 59	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
 60	            BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
 61	            subtotal = packagePrice;
 62	            discount = cents(BigDecimal.ZERO);
 63	            total = packagePrice;
 64	        } else {
 65	            discount = switch (ratePlan) {
 66	                case STANDARD -> cents(BigDecimal.ZERO);
 67	                case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 68	                case CORPORATE -> {
 69	                    BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
 70	                    yield cents(subtotal.multiply(discountRate));
 71	                }
 72	                case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 73	                default -> cents(BigDecimal.ZERO);
 74	            };
 75	            total = subtotal.subtract(discount);
 76	        }
 77	
 78	        return new Price(nights, subtotal, discount, total);
 79	    }
 80	
 81	    BigDecimal nightPrice(Room room, LocalDate night) {
 82	        BigDecimal nightlyRate = room.nightlyRate();
 83	        if (isHighSeason(night)) {
 84	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 85	        }
 86	        return cents(nightlyRate);
 87	    }
 88	
 89	    /** High season: from December 15 to the end of February, and the whole of July. */
 90	    static boolean isHighSeason(LocalDate date) {
 91	        Month month = date.getMonth();
 92	        return month == Month.JANUARY
 93	                || month == Month.FEBRUARY
 94	                || month == Month.JULY
 95	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 96	    }
 97	
 98	    static BigDecimal cents(BigDecimal value) {
 99	        return value.setScale(2, RoundingMode.HALF_EVEN);
100	    }
101	}
102	package hotel.reservations;
103	
104	import hotel.documents.ReservationReceipt;
105	import hotel.messages.EmailSender;
106	import hotel.rooms.Room;
107	import hotel.rooms.Rooms;
108	import java.math.BigDecimal;
109	
110	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
111	public final class ReservationService {
112	
113	    static final String HOTEL_NAME = "Pousada Maré Alta";
114	
115	    private final Rooms rooms;
116	    private final ReservationStore store;
117	    private final PriceCalculator priceCalculator;
118	    private final EmailSender emailSender;
119	
120	    public ReservationService(
121	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
122	        this.rooms = rooms;
123	        this.store = store;
124	        this.priceCalculator = priceCalculator;
125	        this.emailSender = emailSender;
126	    }
127	
128	    public synchronized Reservation create(NewReservation request) {
129	        if (!request.checkOut().isAfter(request.checkIn())) {
130	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
131	        }
132	        if (request.guests() < 1) {
133	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
134	        }
135	        Room room = rooms.find(request.roomNumber())
136	                .orElseThrow(() -> new HotelException(
137	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
138	        if (request.guests() > room.capacity()) {
139	            throw new HotelException(
140	                    ErrorCode.CAPACITY_EXCEEDED,
141	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
142	        }
143	
144	        validateRatePlanRules(request);
145	
146	        boolean roomTaken = store.all().stream()
147	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
148	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
149	        if (roomTaken) {
150	            throw new HotelException(
151	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
152	        }
153	        Price price =
154	                priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
155	        Reservation reservation = new Reservation(store.nextId(), request, price);
156	        store.save(reservation);
157	        return reservation;
158	    }
159	
160	    private void validateRatePlanRules(NewReservation request) {
161	        switch (request.ratePlan()) {
162	            case CORPORATE -> {
163	                if (request.companyCode() == null
164	                        || !PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
165	                    throw new HotelException(
166	                            ErrorCode.INVALID_REQUEST, "CORPORATE rate plan requires a valid company code");
167	                }
168	            }
169	            case WEEKEND_PACKAGE -> {
170	                if (request.checkIn().getDayOfWeek() != java.time.DayOfWeek.FRIDAY
171	                        || request.checkOut().getDayOfWeek() != java.time.DayOfWeek.SUNDAY
172	                        || !request.checkOut().equals(request.checkIn().plusDays(2))) {
173	                    throw new HotelException(
174	                            ErrorCode.INVALID_REQUEST,
175	                            "WEEKEND_PACKAGE requires check-in on Friday and check-out on Sunday");
176	                }
177	            }
178	            case LONG_STAY -> {
179	                long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
180	                if (nights < 7) {
181	                    throw new HotelException(
182	                            ErrorCode.INVALID_REQUEST, "LONG_STAY requires at least 7 nights");
183	                }
184	            }
185	        }
186	    }
187	
188	    public Reservation find(long reservationId) {
189	        return store.find(reservationId)
190	                .orElseThrow(() -> new HotelException(
191	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
192	    }
193	
194	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
195	    public synchronized Reservation confirm(long reservationId) {
196	        Reservation reservation = find(reservationId);
197	        if (reservation.status() != ReservationStatus.PENDING) {
198	            throw notAllowed(reservation, "confirm");
199	        }
200	        reservation.confirmPayment();
201	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
202	        emailSender.send(
203	                reservation.guest().email(),
204	                "Reserva confirmada - " + HOTEL_NAME,
205	                confirmationEmailBody(reservation, receipt));
206	        return reservation;
207	    }
208	
209	    /**
210	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
211	     * reservation was never paid, so nothing comes back).
212	     */
213	    public synchronized Reservation cancel(long reservationId) {
214	        Reservation reservation = find(reservationId);
215	        if (reservation.status() != ReservationStatus.PENDING
216	                && reservation.status() != ReservationStatus.CONFIRMED) {
217	            throw notAllowed(reservation, "cancel");
218	        }
219	        BigDecimal refund = switch (reservation.ratePlan()) {
220	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
221	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
222	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(
223	                    new BigDecimal("2"), 2, java.math.RoundingMode.HALF_EVEN));
224	        };
225	        reservation.cancel(refund);
226	        return reservation;
227	    }
228	
229	    public synchronized Reservation checkIn(long reservationId) {
230	        Reservation reservation = find(reservationId);
231	        if (reservation.status() != ReservationStatus.CONFIRMED) {
232	            throw notAllowed(reservation, "check in");
233	        }
234	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
235	        return reservation;
236	    }
237	
238	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
239	    public synchronized ReservationReceipt checkOut(long reservationId) {
240	        Reservation reservation = find(reservationId);
241	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
242	            throw notAllowed(reservation, "check out");
243	        }
244	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
245	        return new ReservationReceipt(reservation, roomOf(reservation));
246	    }
247	
248	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
249	    public ReservationReceipt receiptCopy(long reservationId) {
250	        Reservation reservation = find(reservationId);
251	        if (!reservation.isPaid()) {
252	            throw notAllowed(reservation, "issue a receipt for");
253	        }
254	        return new ReservationReceipt(reservation, roomOf(reservation));
255	    }
256	
257	    private Room roomOf(Reservation reservation) {
258	        return rooms.find(reservation.roomNumber()).orElseThrow();
259	    }
260	
261	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
262	        return "Olá, " + reservation.guest().name() + "!\n\n"
263	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
264	                + receipt.text() + "\n"
265	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
266	                + "Até breve!\n";
267	    }
268	
269	    private static HotelException notAllowed(Reservation reservation, String operation) {
270	        return new HotelException(
271	                ErrorCode.OPERATION_NOT_ALLOWED,
272	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
273	    }
274	}

